Item.method_code:
setTimeout(() => {
	const isNew = this.aras.isTempEx(this.aras.getMostTopWindowWithAras(window).item);

	if (!isNew) {
		const applicationField = this.getFieldByName('application');
		const applicationFieldId = applicationField.id.replace('span', '');
		const applicationComponent = this['field' + applicationFieldId + 'Component'];

		if (applicationComponent && applicationComponent.getValue()) {
			applicationComponent.setReadOnly(true);
		}
	}
}, 0);
